"""Validate Ram's declared candidate ownership/codec demand; metadata only."""
import ast,hashlib,json,subprocess
from pathlib import Path
PIN='18712a57ec5f55cd99bbcbe4cc6b64027d11bd20'
CENSUS='db83b444c5c8f905e5f3903a605ea52190cc0f5e'
CP='results/quality/w16_w17_nonexpert_header_census_20261001/census.json'
OUT=Path('results/quality/w16_dsrom_embedding_head_home_20261001')
def read(c,p):return subprocess.check_output(['git','show',c+':'+p])
def sha(b):return hashlib.sha256(b).hexdigest()
def bf_slot(column):
 h,rem=divmod(column,128);lane,b=divmod(rem,8);return h*8+b,lane

def main():
 raw=read(CENSUS,CP);cat=json.loads(raw);sr=read(PIN,'tools/rtl_v41_rom_array.py');tree=ast.parse(sr);fn=next(n for n in tree.body if isinstance(n,ast.FunctionDef) and n.name=='bf16_word')
 V,D=cat['tensors']['embed.weight']['stored_shape'];assert cat['tensors']['head.weight']['stored_shape']==[V,D] and all(cat['tensors'][k]['dtype']=='BF16' for k in ('embed.weight','head.weight'))
 TP=4;assert V%TP==0 and D%128==0;q=V//TP;words=q*(D//16);cap=1024*2*8192
 quarters=[dict(rank=r,global_vocab_rows=[r*q,(r+1)*q],local_rows=q,columns=[0,D],words=words,payload_BF16_bytes=q*D*2,physical_container_bits_required=words*274,logical_word_interval=[0,words],physical_region_base=None,physical_field_id=None,physical_allocator_hash=None) for r in range(TP)]
 # Exact metadata owner partition and 16lane word mapping coverage, no tensors loaded.
 for token in range(V):
  owner,local=divmod(token,q);assert 0<=owner<4 and 0<=local<q and owner*q+local==token
 slots={bf_slot(col) for col in range(D)};assert len(slots)==D and slots=={(w,l) for w in range(D//16) for l in range(16)}
 totalwords=2*words;assert totalwords>cap and words<=cap
 prior=json.loads(Path('results/quality/w16_dsrom_maintext_binding_recipes_20261001/contract.json').read_text());layers=prior['summary']['CROM_reference_words_by_layer'];crom={L:dict(logical64bit_words=n,three_per_274_container_words=(n+2)//3,padded64bit_slots=3*((n+2)//3)-n,physical_region_base=None) for L,n in layers.items()}
 out=dict(schema='opentallas.dsrom.embedding-head.ROM-candidate-home-validation.v1',status='PASS_METADATA_OWNERSHIP_SINGLE_SHARED_FIELD_CAPACITY_FAIL_PHYSICAL_UNQUALIFIED',census_commit=CENSUS,census_path=CP,census_sha256=sha(raw),codec_source_commit=PIN,codec_path='tools/rtl_v41_rom_array.py',codec_source_sha256=sha(sr),bf16_word_function_sha256=sha(ast.get_source_segment(sr.decode(),fn).encode()),generator_sha256=sha(Path(__file__).read_bytes()),architecture_owner='Ram 01a0f697-9c82-7572-8900-dd7b15d59ebf',choice_provenance='Ram direct owner message: immutable BF16 vocabquarters TP4; embedding oneowner/token then4rank broadcast; head fullK activation broadcast and orderedrankargmax64b; BF274 16lanes/word; dedicatedBF1024pairbudget; CROM3x64candidate',tensor_homes={k:dict(home_choice='immutable ROM candidate',vocabulary_quarters=quarters,one_full_table_logical_copy=True,physical_full_table_replicas=None,physical_field_count=None,actual_image_producer=None) for k in ('embed.weight','head.weight')},lookup=dict(token_owner_formula='token_id //32320',owner_local_row_formula='token_id %32320',logical_row_word_formula='local_row*320 + h*8+b',lane_element_formula='h*128+lane*8+b',token_row_stored_bytes=10240,token_row_words=320,rank_consumers=4,wire_BF16_row_bytes_per_receiver=10240,distinct_remote_receiver_count=3,minimum_remote_payload_bytes_if_owner_local=30720,physical_fabric_edges=None,physical_send_count=None,owner_read_commands_per_token=320,port_service_at_one_word_per_cycle_cycles=320,physical_port_proof=None),head=dict(input_BF16_activation_bytes=10240,all_ranks_fullK=True,K_split=False,per_rank_output_logits=q,per_rank_weight_read_words=words,per_rank_useful_weight_read_bytes=q*D*2,reference_16lane_MACs_per_word=16,per_rank_MACs=q*D,rankargmax_payload_bits=64,ordered_rank_combine='rank0,rank1,rank2,rank3; tie/NaN behavior must bind exactgolden',actual_combine_schedule=None,actual_finalnorm_base=None),field_capacity=dict(BF_pair_slots=1024,macros_per_pair=2,depth_words_per_macro=8192,capacity_words_per_rank_field=cap,each_tensor_words_per_rank=words,each_tensor_capacity_only_fits=True,combined_words_per_rank=totalwords,combined_single_field_fits=False,combined_single_field_excess_words=totalwords-cap,physical_fit_claim=False,required='separate producer/region field namespaces or admitted allocator; no silentsharedfieldfit'),CROM_candidate=dict(format='3logical64bit words in274bit container;82bits unused',proposed_container_formula='logical_word_address//3',proposed_slot_formula='logical_word_address%3',slot_bit_ranges=[[0,63],[64,127],[128,191]],spare_bit_range=[192,273],per_layer_reference_view=crom,finalnorm_logical64bit_words=5120,embedding_head_norm_physical_owner=None,port_constraint='A single274bitread gives only3co-resident64bitaddresses, not3arbitrarylogicaladdresses. Existing4*SW+aux+XS reads require actualbanking/arbitration/issue proof.',actual_unpack_producer=None,actual_unpack_RTL=None,admission=False),verification=dict(vocabulary_owner_partition_all129280_tokens_exact=True,BF16_word_slots_all5120_columns_exact=True,header_dtype_shapes_exact=True,payload_reads=0,RTL_or_PnR_runs=0),mandatory_gaps=['actualembedding/head274bit imageproducer withfield-regionbase and segmentallocator proof','BF rowsegment allocator respecting golden reduction order and actualreadports','headfinalnormbase and exactorderedargmax tie/NaN contract','CROM physical bank/ports,address-base nonoverlap and3slot unpack contract','fullgeometry integration of separateembedding/head fields and allothermaintext homes'],physical_capacity_credit=False,admission_claim=False,product_complete=False)
 OUT.mkdir(parents=True,exist_ok=True)
 (OUT/'contract.json').write_text(json.dumps(out,indent=2,sort_keys=True)+'\n');(OUT/'SHA256SUMS').write_text(sha((OUT/'contract.json').read_bytes())+'  contract.json\n')
 print(json.dumps(out['field_capacity']))
if __name__=='__main__':main()
